/* From Uiverse.io by Cksunandh  - Tags: switch */
.__UIV_SCOPE__ .toggle-switch {
  position: relative;
  width: 60px;
  height: 30px;
  border-radius: 15px;
  background-color: #ffffff;
  box-shadow:
    inset 5px 5px 10px #c1c1c1,
    inset -5px -5px 10px #ffffff;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.__UIV_SCOPE__ .toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .toggle-switch .slider {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  box-shadow:
    2px 2px 5px #c1c1c1,
    -2px -2px 5px #ffffff;
  transition: transform 0.3s ease;
}

.__UIV_SCOPE__ .toggle-switch input:checked + .slider {
  transform: translateX(30px);
}

.__UIV_SCOPE__ .toggle-switch input:checked {
  background-color: #ffffff;
}
